# Definition for a binary tree node.
class TreeNode:
    def __init__(self, x):
        self.val = x
        self.left = None
        self.right = None

# Recursive
class Solution:
    def pluck(self, root):
        if not root:
            return []

        smallest, smallest_index = self.get_smallest_value_and_index(root)

        if smallest == float("inf"):
            return []

        return [smallest, smallest_index]

    def get_smallest_value_and_index(self, node):
        if not node:
            return float("inf"), -1

        if not node.left and not node.right:
            if node.val % 2 == 0:
                return node.val, 0
            else:
                return float("inf"), -1

        # Recursively find the smallest value and its index
        left_value, left_index = self.get_smallest_value_and_index(node.left)
        right_value, right_index = self.get_smallest_value_and_index(node.right)

        # Check if the current node has a smaller even value
        if node.val % 2 == 0 and (node.val < left_value or node.val < right_value):
            return node.val, 0

        # Check if the left subtree has a smaller even value
        if left_value < right_value:
            return left_value, left_index + 1
        else:
            return right_value, right_index + 1 + len(node.left.left)

# Iterative
class Solution:
    def pluck(self, root):
        if not root:
            return []

        # Initialize variables to track the smallest even value and its index
        smallest = float("inf")
        smallest_index = -1

        # Perform a breadth-first search to find the smallest even value
        queue = [(root, 0)]
        while queue:
            node, index = queue.pop(0)
            if node.val % 2 == 0 and node.val < smallest:
                smallest = node.val
                smallest_index = index

            if node.left:
                queue.append((node.left, index * 2 + 1))
            if node.right:
                queue.append((node.right, index * 2 + 2))

        if smallest == float("inf"):
            return []

        return [smallest, smallest_index]
```
