def count_nums(arr):
    """
    This function takes an array of integers and returns the number of elements which have a sum of digits greater than 0.
    If a number is negative, the first signed digit will be negative.

    Examples:
    >>> count_nums([])
    0
    >>> count_nums([-1, 11, -11])
    1
    >>> count_nums([1, 1, 2])
    3
    """
    def signed_digits(n):
        if n < 0:
            return [-int(str(n)[1]), *signed_digits(int(str(n)[2:]))]
        elif n == 0:
            return []
        else:
            return [n]

    def digit_sum(lst):
        return sum(lst)

