# QuickSelect approach: Time: O(n) avg, Time: O(n^2) worst, Space: O(1)
def maxKElements(self, arr, k):
    if k == 0:
        return []

    def quickSelect(left, right, k):
        if left == right:
            return arr[left]

        p = left
        pivot = arr[left]
        while left < right:
            while left < right and arr[right] < pivot:
                right -= 1
            arr[left], arr[right] = arr[right], arr[left]
            while left < right and arr[left] >= pivot:
                left += 1
            arr[left], arr[right] = arr[right], arr[left]

        if left == k:
            return arr[left]

        if k < left:
            return quickSelect(left, p-1, k)
        else:
            return quickSelect(left+1, right, k)

    return quickSelect(0, len(arr)-1, k-1)[::-1]

