### **Reservoir Sampling**
```python
class Solution:
    def sumTwoDigitsNumbers(self, arr: List[int], k: int) -> int:
        from random import randint
        result = 0
        for i in range(k):
            if 10 <= arr[i] <= 99:
                result += arr[i]
                for j in range(i+1, k):
                    if randint(1, i+1) <= k-1:
                        result -= arr[i]
                        arr[i] = arr[j]
                        break
        return result
```

### **Heap**
```python
class Solution:
    def sumTwoDigitsNumbers(self, arr: List[int], k: int) -> int:
        heap = []
        for num in arr[:k]:
            if 10 <= num <= 99:
                heapq.heappush(heap, num)
        return sum(heap)
