def tri(n):
    """Returns the first n + 1 numbers of the Tribonacci sequence."""
    if n == 0:
        return [0]
    elif n == 1:
        return [1, 3]
    elif n == 2:
        return [1, 3, 2]

    sequence = [0, 1, 3]
    for i in range(3, n + 1):
        if i % 2 == 0:
            next_value = 1 + i / 2
        else:
            next_value = sequence[i - 1] + sequence[i - 2] + sequence[i + 1]
        sequence.append(next_value)

